from typing import List

class Solution:
    def rob(self, nums: List[int]) -> int:
        if len(nums) == 1:
            return nums[0]

        def dfs(lo: int, hi: int, i: int) -> int:
            if i > hi:
                return 0
            return max(nums[i] + dfs(lo, hi, i + 2), dfs(lo, hi, i + 1))

        return max(dfs(0, len(nums) - 2, 0), dfs(1, len(nums) - 1, 1))

