from typing import List

class Solution:
    def rob(self, nums: List[int]) -> int:
        if len(nums) == 1:
            return nums[0]

        def solve(lo: int, hi: int) -> int:
            memo = {}

            def dfs(i: int) -> int:
                if i > hi:
                    return 0
                if i not in memo:
                    memo[i] = max(nums[i] + dfs(i + 2), dfs(i + 1))
                return memo[i]

            return dfs(lo)

        return max(solve(0, len(nums) - 2), solve(1, len(nums) - 1))

